//! ♻️ Original slot retirement returns its immutable source before paying the captured payload issuer.
use super::*;
use semio_framework_value_retirement::{RetireOwned,retirement::{RetirementCursor,RetirementStep}};
use semio_framework_value_retained_clone::RetainedCloneClose;
use crate::{FactoryAuthority,ErasedSnapshotRetirement};
#[doc(hidden)]
pub struct OriginalSlotRetirement<T:RetireOwned>{slot:ManuallyDrop<Option<RetainedOriginalSlot<T>>>,payload:ManuallyDrop<Option<T>>,factory:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<T>>>>,active:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,intrinsic:RetainedCloneClose,factory_close:Option<FactoryAuthority>}
impl<T:RetireOwned> OriginalSlotRetirement<T>{
 fn demand(&self,body:usize)->Result<RetirementDemand,ValueError>{
  if let Some(slot)=self.slot.as_ref(){return if slot.has_read(){slot.return_demands(slot.key(),body)}else{Ok(RetirementDemand{copy_bytes:size_of::<RetainedOriginalSlot<T>>()+size_of::<T>(),depth:1,..Default::default()})};}
  if let Some(active)=self.active.as_ref(){return crate::factory_ticket_demands(active,body);}
  if !self.intrinsic.is_empty(){return self.intrinsic.next_owner_demands::<T>(false,&None,body);}
  if self.payload.is_some(){return if self.factory.is_some(){Ok(crate::FactoryOwnedRetirement::<T>::original_admission_demands(&self.payload))}else{self.intrinsic.next_owner_demands::<T>(true,&None,body)};}
  if self.factory.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<FactoryAuthority>()+size_of::<Arc<dyn ArtifactOwnedValueRetirementFactory<T>>>(),depth:1,..Default::default()});}
  self.factory_close.as_ref().map_or(Ok(Default::default()),|factory|if factory.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<FactoryAuthority>>(),depth:1,..Default::default()})}else{factory.demands(body)})
 }
 fn step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{
  let grant=effect.grant();let demand=match self.demand(grant.maximum_copy_bytes){Ok(demand)=>demand,Err(error)=>return Self::done(Err(error.into()),0)};let work=match self.next_computational_work(grant.maximum_copy_bytes){Ok(work)=>work,Err(error)=>return Self::done(Err(error.into()),0)};if effect.maximum_work_units()<work||!retained_clone_grant_admits(grant,demand){return Self::done(Ok(RetainedCloneStep::Progress(Default::default())),0)}
  if let Some(slot)=self.slot.as_mut(){if slot.has_read(){return crate::RetainedWorkPoll::Complete(slot.return_read(slot.key(),&mut self.factory,effect)).map_err(Into::into)}let work=match semio_framework_value_retirement::retirement::record_retirement_work(effect,1){Ok(work)=>work,Err((error,work))=>return Self::done(Err(error.into()),work)};let slot=self.slot.take().expect("funded original slot");if !slot.is_empty(){let original=slot.try_into_original().unwrap_or_else(|_|panic!("quoted original slot returned every immutable reader"));*self.payload=Some(original)}return Self::done(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work)}
  if self.active.is_some(){return crate::close_factory_ticket(&mut self.active,effect)}if !self.intrinsic.is_empty(){return self.intrinsic.step_granted(effect)}if self.payload.is_some(){if self.factory.is_some(){return crate::FactoryOwnedRetirement::<T>::admit_original(&mut self.payload,&mut self.factory,&mut self.active,effect).map_err(Into::into)}let turn=self.intrinsic.begin_granted(&mut self.payload,effect);return Self::done(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),turn.work)}
  if self.factory.is_some(){let work=match semio_framework_value_retirement::retirement::record_retirement_work(effect,1){Ok(work)=>work,Err((error,work))=>return Self::done(Err(error.into()),work)};self.factory_close=Some(FactoryAuthority::new(self.factory.take().expect("funded original factory")));return Self::done(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work)}if let Some(factory)=self.factory_close.as_mut(){if !factory.terminal_is_empty(){return factory.step(effect)}let work=match semio_framework_value_retirement::retirement::record_retirement_work(effect,1){Ok(work)=>work,Err((error,work))=>return Self::done(Err(error.into()),work)};self.factory_close=None;return Self::done(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work)}Self::done(Ok(RetainedCloneStep::Complete(Default::default())),0)
 }
 fn done(result:Result<RetainedCloneStep,crate::OriginalRetirementFailure>,work:u128)->semio_framework_value_retirement::OriginalRetirementPoll{crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result,work})}
 fn empty(&self)->bool{self.slot.is_none()&&self.payload.is_none()&&self.factory.is_none()&&self.active.is_none()&&self.intrinsic.is_empty()&&self.factory_close.is_none()}
}
impl<T:RetireOwned> RetireOwned for RetainedOriginalSlot<T>{type RetirementCursor=OriginalSlotRetirement<T>;fn retirement_seed(self)->Self::RetirementCursor{OriginalSlotRetirement{slot:ManuallyDrop::new(Some(self)),payload:ManuallyDrop::new(None),factory:ManuallyDrop::new(None),active:ManuallyDrop::new(None),intrinsic:Default::default(),factory_close:None}}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<OriginalSlotRetirement<T>>())}fn controlled_retirement_supported()->bool{true}}
impl<T:RetireOwned> RetirementCursor for OriginalSlotRetirement<T>{fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{if let Some(slot)=self.slot.as_ref(){return if slot.has_read(){slot.return_work_demand(slot.key(),body)}else{Ok(1)}}if let Some(active)=self.active.as_ref(){return if active.terminal_is_empty(){Ok(1)}else{active.next_computational_work(body)}}if !self.intrinsic.is_empty(){return self.intrinsic.next_owner_work::<T>(false,&None,body)}if self.payload.is_some(){return if self.factory.is_some(){Ok(crate::FactoryOwnedRetirement::<T>::admit_original_source_work_demand(&self.payload))}else{self.intrinsic.next_owner_work::<T>(true,&None,body)}}if self.factory.is_some(){return Ok(1)}self.factory_close.as_ref().map_or(Ok(0),|f|f.next_computational_work(body))}fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.demand(body)}fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{semio_framework_value_retirement::retirement::erased_cursor_turn(self.step(effect))}fn terminal_is_empty(&self)->bool{self.empty()}fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.demand(0)?.copy_bytes)}fn next_birth_bytes(&self,b:usize)->Option<usize>{self.demand(b).ok().map(|d|d.capacity_bytes)}fn next_close_byte_demand(&self)->Option<usize>{self.demand(0).ok().map(|d|d.release_bytes)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.demand(0)?.depth)}fn terminal_release_bytes(&self)->Option<usize>{self.empty().then_some(size_of::<Self>())}}
impl<T:RetireOwned> Drop for OriginalSlotRetirement<T>{fn drop(&mut self){assert!(self.empty()||std::thread::panicking(),"original slot retirement dropped before same issuer payload closure");if self.empty(){unsafe{ManuallyDrop::drop(&mut self.slot);ManuallyDrop::drop(&mut self.payload);ManuallyDrop::drop(&mut self.factory);ManuallyDrop::drop(&mut self.active);}}}}
